// Build-time only: iOS receives a self-contained PNG, with no native Node dependency.
const fs = require('node:fs'),
  path = require('node:path')
const { Resvg } = require('@resvg/resvg-js')
const { harness } = require('./harness.cjs')
const svg = harness().load('brand-icons.ts').openaiIcon
const png = new Resvg(svg, {
  fitTo: { mode: 'width', value: 120 },
  background: '#FFFFFF',
})
  .render()
  .asPng()
const root = path.resolve(__dirname, '..')
fs.writeFileSync(path.join(root, 'assets/openai.png'), png)
fs.writeFileSync(
  path.join(root, 'brand-raster.ts'),
  '// Generated by tools/brand-raster.cjs from the CC0 OpenAI artwork in brand-icons.ts.\nexport const openaiPNG = ' +
    JSON.stringify(png.toString('base64')) +
    '\n',
)
console.log('Built offline OpenAI PNG: 120 × 120, ' + png.length + ' bytes')
